<section><div class="page-heading"><div><p class="eyebrow">Security trail</p><h1>Audit log</h1><p class="muted">Sensitive administrative and merchant actions. Metadata is escaped and passwords or tokens are never intentionally recorded.</p></div><span><?= e($result['total']) ?> events</span></div><form class="admin-filters" method="get" action="/sa/audit"><input type="search" name="q" value="<?= e($filters['q']) ?>" placeholder="Event, actor email, or target type" aria-label="Search audit log"><select name="event" aria-label="Event type"><option value="">All events</option><?php foreach($events as$event):?><option value="<?= e($event) ?>" <?= $filters['event']===$event?'selected':'' ?>><?= e($event) ?></option><?php endforeach ?></select><button class="button secondary">Filter</button></form><section class="panel flush"><div class="table-wrap"><table><thead><tr><th>Event</th><th>Actor</th><th>Target</th><th>IP</th><th>Time</th></tr></thead><tbody><?php foreach($result['items']as$row):?><tr><td><strong><?= e($row['event']) ?></strong></td><td><?= e($row['actor_name']??'System') ?><small><?= e($row['actor_email']??'') ?></small></td><td><?= e($row['target_type']??'—') ?><?= $row['target_id']?' #'.e($row['target_id']):'' ?></td><td><?= e($row['ip_address']??'—') ?></td><td><?= e($row['created_at']) ?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$result['items']):?><div class="empty-inline padded">No audit events match these filters.</div><?php endif ?></section><?php $base=['q'=>$filters['q'],'event'=>$filters['event']];?><nav class="admin-pagination" aria-label="Audit pages"><?php if($result['page']>1):?><a href="?<?= e(http_build_query($base+['page'=>$result['page']-1])) ?>">← Previous</a><?php endif ?><span>Page <?= e($result['page']) ?> of <?= e($result['pages']) ?></span><?php if($result['page']<$result['pages']):?><a href="?<?= e(http_build_query($base+['page'=>$result['page']+1])) ?>">Next →</a><?php endif ?></nav></section>
